package net.battlespades.session;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import net.battlespades.combat.*;
import net.battlespades.match.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.PlayerLife;
import net.battlespades.protocol.ShootPacket;
import net.battlespades.world.JsonData;
import org.tomlj.TomlTable;

/** Host-owned review population and worker-owned rotating journal. Owner snapshots never retain retired worlds. */
public final class HostedAnticheatReview implements AutoCloseable {
    private static final ShotTally.Snapshot EMPTY=new ShotTally.Snapshot(0,0,0,0,Map.of(),Map.of());
    private static final class Entry {
        PlayerLife player;String key;final AnticheatReview.Aim aim=new AnticheatReview.Aim();ShotTally.Snapshot base=EMPTY;
        final Map<String,Long> violations=new LinkedHashMap<>();final Map<String,Map<String,Long>> histograms=new LinkedHashMap<>();final ArrayDeque<Integer> delays=new ArrayDeque<>();long kills,heads;boolean profile;
        Entry(PlayerLife p){player=p;}
    }
    private record Track(double firstSeen,AnticheatReview.Evidence evidence){}
    private record Archived(String key,int tool,double accuracy){}
    private final Thread owner=Thread.currentThread();private final ApplicationHost host;private final AnticheatReview.Settings settings;private final boolean enabled;
    private final Path path;private final long maxBytes;private final int backups;
    private final ThreadPoolExecutor journal=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(64),Thread.ofPlatform().daemon().name("anticheat-journal").factory(),new ThreadPoolExecutor.AbortPolicy());
    private final Map<JoinSession,Entry> entries=new IdentityHashMap<>();private final Map<String,Track> tracks=new LinkedHashMap<>();private final ArrayDeque<Archived> archive=new ArrayDeque<>();
    private Double lastSummary;private boolean submitted,stopping;private volatile boolean stopped;private CompletionStage<Void> shutdown;
    public HostedAnticheatReview(ApplicationHost host,TomlTable raw){this.host=Objects.requireNonNull(host);settings=AnticheatReview.Settings.from(raw);enabled=raw.getBoolean("anticheat.report_enabled",()->true);path=Path.of(raw.getString("anticheat.report_path",()->"logs/anticheat.jsonl")).toAbsolutePath();maxBytes=raw.getLong("anticheat.report_max_bytes",()->5_000_000L);long count=raw.getLong("anticheat.report_backups",()->3L);if(count>100)throw new IllegalArgumentException("anticheat.report_backups must be <= 100");backups=(int)Math.max(0,count);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Anticheat review outside owner");}
    private JoinSession session(PlayerLife p){return host.transitionSessions().stream().filter(s->s.playerId().orElse(-1)==p.id()).findFirst().orElse(null);}
    private Entry entry(PlayerLife p){owned();var existing=entries.values().stream().filter(e->e.player==p).findFirst().orElse(null);if(existing!=null)return existing;var s=session(p);if(s==null)return null;var e=entries.computeIfAbsent(s,k->{var added=new Entry(p);added.key="ip:"+s.addressHost()+":"+p.name();return added;});if(e.player==null)e.player=p;if(e.player!=p)throw new IllegalStateException("Retired life used for review");return e;}
    private String key(PlayerLife p){var existing=entries.values().stream().filter(e->e.player==p).findFirst().orElse(null);if(existing!=null)return existing.key;String address=host.addressHost(p.id()).orElse(null);return address==null||address.equals("unknown")?"player:"+p.id()+":"+p.name():"ip:"+address+":"+p.name();}
    public void observe(StandardMatchDomain match,PlayerLife p,ShootPacket packet,double now){owned();if(stopping||p.bot()||!AnticheatReview.hitscan(p.inventory().tool()))return;var e=entry(p);if(e==null)return;var origin=packet.origin();var d=packet.direction();var targets=match.lives().players().stream().filter(t->t!=p&&t.alive()&&t.spawned()&&t.team()!=p.team()).map(t->new AnticheatReview.Target(t.id(),t.team(),t.position())).toList();e.aim.observe(settings,p.team(),packet.loopCount(),new Vector(origin.x(),origin.y(),origin.z()),new Vector(d.x(),d.y(),d.z()),targets,p.motion()::eyeAt,match.world()::solid,now);}
    private static ShotTally.Snapshot plus(ShotTally.Snapshot a,ShotTally.Snapshot b){var weapons=new LinkedHashMap<>(a.weapons());b.weapons().forEach((tool,w)->weapons.merge(tool,w,(x,y)->new ShotTally.Weapon(x.shots()+y.shots(),x.hits()+y.hits(),x.headshots()+y.headshots())));var seeds=new LinkedHashMap<>(a.seeds());merge(seeds,b.seeds());return new ShotTally.Snapshot(a.shots()+b.shots(),a.hits()+b.hits(),a.headshots()+b.headshots(),a.pelletHits()+b.pelletHits(),weapons,seeds);}
    private static <K> void merge(Map<K,Long> target,Map<K,Long> source){source.forEach((k,v)->target.merge(k,v,Long::sum));}
    private ShotTally.Snapshot shots(PlayerLife p,Entry e){return e==null?p.combatStatistics().snapshot():plus(e.base,p.combatStatistics().snapshot());}
    private Map<String,Long> counts(PlayerLife p,Entry e){var result=new LinkedHashMap<String,Long>();if(e!=null)result.putAll(e.violations);merge(result,p.anticheat().counts());return result;}
    private AnticheatReview.Evidence evidence(StandardMatchDomain match,PlayerLife p){var e=p.bot()?null:entry(p);var kills=AnticheatReview.profileKills(match.binding().row(p).profileStats);boolean profile=kills!=null||e!=null&&e.profile;long k=(kills==null?0:kills[0])+(e==null?0:e.kills),h=(kills==null?0:kills[1])+(e==null?0:e.heads);var track=tracks.get(key(p));return new AnticheatReview.Evidence(p.id(),p.name(),p.bot(),shots(p,e),profile?k:null,profile?h:null,e==null?AnticheatReview.AimSnapshot.empty():e.aim.snapshot(),counts(p,e),track==null?Double.NaN:track.firstSeen);}
    /** Snapshot before detach, including map transitions, without keeping a PlayerLife/world in the archive. */
    public void depart(StandardMatchDomain match,PlayerLife p,boolean transition){owned();if(stopping||p.bot())return;var pair=entries.entrySet().stream().filter(v->v.getValue().player==p).findFirst().orElse(null);var s=pair==null?session(p):pair.getKey();var e=pair==null?null:pair.getValue();var snapshot=evidence(match,p);var old=tracks.get(key(p));if(old!=null)tracks.put(key(p),new Track(old.firstSeen,snapshot));if(e==null&&s!=null)e=entries.get(s);if(e==null)return;
        e.base=snapshot.shots();e.violations.clear();e.violations.putAll(snapshot.violations());if(snapshot.hitscanKills()!=null){e.profile=true;e.kills=snapshot.hitscanKills();e.heads=snapshot.headshotKills();}
        var retained=e;p.shotStatistics().histograms().forEach((k,v)->merge(retained.histograms.computeIfAbsent(k,x->new LinkedHashMap<>()),v));for(var delay:p.motion().snapshot().queueDelays()){e.delays.addLast(delay);while(e.delays.size()>600)e.delays.removeFirst();}e.player=null;if(!transition)entries.remove(s);
    }
    private Map<Integer,List<Double>> population(StandardMatchDomain match,PlayerLife exclude){var result=new HashMap<Integer,List<Double>>();var live=new HashSet<String>();for(var p:match.lives().players()){if(p.bot())continue;live.add(key(p));if(p!=exclude)AnticheatReview.accuracies(evidence(match,p).shots(),settings).forEach((tool,accuracy)->result.computeIfAbsent(tool,k->new ArrayList<>()).add(accuracy));}for(var row:archive)if(!live.contains(row.key))result.computeIfAbsent(row.tool,k->new ArrayList<>()).add(row.accuracy);return result;}
    public AnticheatReview.Report analyze(StandardMatchDomain match,PlayerLife p){owned();return AnticheatReview.analyze(settings,evidence(match,p),population(match,p),match.monotonic());}
    public List<AnticheatReview.Report> analyzeAll(StandardMatchDomain match){owned();return match.lives().players().stream().filter(p->!p.bot()).map(p->analyze(match,p)).sorted(Comparator.comparingDouble(AnticheatReview.Report::score).reversed().thenComparingInt(AnticheatReview.Report::playerId)).toList();}
    public Map<String,Object> raw(StandardMatchDomain match,PlayerLife p){owned();var e=p.bot()?null:entry(p);var evidence=evidence(match,p);var s=evidence.shots();var aim=evidence.aim();var raw=new LinkedHashMap<String,Object>();var row=match.binding().row(p);
        raw.put("player_id",p.id());raw.put("name",p.name());raw.put("kills",row.kills);raw.put("deaths",row.deaths);raw.put("hitscan_kills",evidence.hitscanKills());raw.put("headshot_kills",evidence.headshotKills());raw.put("shots",s.shots());raw.put("hits",s.hits());raw.put("headshots",s.headshots());raw.put("pellet_hits",s.pelletHits());raw.put("pellet_seed_shots",s.seeds().values().stream().mapToLong(Long::longValue).sum());var weapons=new TreeMap<Integer,Object>();s.weapons().forEach((tool,w)->weapons.put(tool,Map.of("shots",w.shots(),"hits",w.hits(),"headshots",w.headshots())));raw.put("weapons",weapons);
        var hist=new LinkedHashMap<String,Map<String,Long>>();if(e!=null)e.histograms.forEach((k,v)->hist.put(k,new LinkedHashMap<>(v)));p.shotStatistics().histograms().forEach((k,v)->merge(hist.computeIfAbsent(k,x->new LinkedHashMap<>()),v));for(var k:List.of("origin_error","origin_error_fallback","aim_angle","aim_angle_fallback","rejected"))raw.put(k,hist.getOrDefault(k,Map.of()));raw.put("violations",evidence.violations());
        var delays=new ArrayList<Integer>();if(e!=null)delays.addAll(e.delays);delays.addAll(p.motion().snapshot().queueDelays());if(delays.size()>600)delays=new ArrayList<>(delays.subList(delays.size()-600,delays.size()));raw.put("input_queue_delay",delays.isEmpty()?Map.of():Map.of("samples",delays.size(),"p50",AnticheatReview.percentile(delays.stream().map(Integer::doubleValue).toList(),50),"max",Collections.max(delays)));
        var a=new LinkedHashMap<String,Object>();a.put("shots",aim.shots());a.put("engaged",aim.engaged());a.put("on_head",aim.onHead());a.put("snaps",aim.snaps());a.put("acquisition_samples",aim.acquisition().size());a.put("acquisition_median_ms",aim.acquisition().isEmpty()?null:AnticheatReview.round(AnticheatReview.percentile(aim.acquisition(),50),1));raw.put("aim",a);return Collections.unmodifiableMap(raw);
    }
    public List<AnticheatReview.Report> tick(StandardMatchDomain match){owned();if(stopping||!enabled)return List.of();try{
        double now=match.monotonic();var live=new HashSet<String>();for(var p:match.lives().players()){if(p.bot())continue;String key=key(p);live.add(key);var previous=tracks.get(key);tracks.put(key,new Track(previous==null?now:previous.firstSeen,evidence(match,p)));}
        for(var key:new ArrayList<>(tracks.keySet()))if(!live.contains(key)){var departed=tracks.remove(key);AnticheatReview.accuracies(departed.evidence.shots(),settings).forEach((tool,accuracy)->{archive.addLast(new Archived(key,tool,accuracy));while(archive.size()>500)archive.removeFirst();});}var sessions=host.transitionSessions();entries.keySet().removeIf(s->!sessions.contains(s));
        if(lastSummary==null){lastSummary=now;return List.of();}if(now-lastSummary<Math.max(1,settings.get("summary_interval_seconds")))return List.of();lastSummary=now;var flagged=analyzeAll(match).stream().filter(AnticheatReview.Report::flagged).toList();if(flagged.isEmpty())return flagged;
        var lines=new StringBuilder();for(var report:flagged){var p=match.lives().player(report.playerId());System.getLogger("anticheat").log(System.Logger.Level.WARNING,"anticheat suspect player={0} name={1} score={2} reasons={3}",p.id(),p.name(),report.score(),report.reasons());var record=new LinkedHashMap<String,Object>(report.data());record.put("ts",Instant.ofEpochMilli((long)(match.wall()*1000)).atOffset(ZoneOffset.UTC).format(java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss'Z'")));record.put("server",match.serverName());record.put("port",match.serverPort());record.put("map",match.mapName());record.put("key",key(p));record.put("stats",raw(match,p));lines.append(JsonData.encode(record));}
        String snapshot=lines.toString();try{journal.execute(()->append(snapshot));submitted=true;}catch(RejectedExecutionException full){System.getLogger("anticheat").log(System.Logger.Level.WARNING,"Anticheat journal queue is full; summary retained in server log");}return flagged;
    }catch(RuntimeException failure){System.getLogger("anticheat").log(System.Logger.Level.DEBUG,"Anticheat review failed",failure);return List.of();}}
    private void append(String snapshot){try{Files.createDirectories(path.getParent());if(maxBytes>0&&Files.exists(path)&&Files.size(path)>=maxBytes){if(backups==0)Files.deleteIfExists(path);else{for(int i=backups-1;i>0;i--){var from=Path.of(path+"."+i);if(Files.exists(from))Files.move(from,Path.of(path+"."+(i+1)),StandardCopyOption.REPLACE_EXISTING);}Files.move(path,Path.of(path+".1"),StandardCopyOption.REPLACE_EXISTING);}}Files.writeString(path,snapshot,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(java.io.IOException failure){System.getLogger("anticheat").log(System.Logger.Level.WARNING,"Cannot write anticheat journal",failure);}}
    public CompletionStage<Void> shutdown(){owned();if(shutdown!=null)return shutdown;stopping=true;if(!submitted){journal.shutdown();stopped=true;shutdown=CompletableFuture.completedFuture(null);return shutdown;}var result=new CompletableFuture<Void>();shutdown=result.minimalCompletionStage();CompletableFuture.runAsync(()->{journal.shutdown();try{while(!journal.awaitTermination(1,TimeUnit.DAYS)){}stopped=true;result.complete(null);}catch(InterruptedException failure){Thread.currentThread().interrupt();result.completeExceptionally(failure);}});return shutdown;}
    @Override public void close(){owned();if(!submitted)shutdown();if(!stopped)throw new IllegalStateException("Await anticheat review shutdown before closing host");entries.clear();tracks.clear();archive.clear();}
}
